// Character classification and case mapping beyond Latin-1 (the semantics of java.lang.Character).
fun main() {
    println("привет".uppercase())
    println("ПРИВЕТ".lowercase())
    println("Ελληνικά".uppercase())
    println("ΕΛΛΗΝΙΚΆ".lowercase())
    println("straße".uppercase())
    println("ŉ".uppercase().length)
    println("ΟΔΥΣΣΕΥΣ".lowercase())
    println("ΑΣ ΒΣΓ".lowercase())
    println("İ".lowercase().length)
    println("ÀÉÎÕÜ àéîõü ÿ µ".uppercase())
    println("日本語のテキスト".uppercase())
    println('я'.isLetter())
    println('日'.isLetter())
    println('ß'.isLowerCase())
    println('ß'.isUpperCase())
    println('Ж'.isUpperCase())
    println('ж'.isLowerCase())
    println('ǅ'.isTitleCase())
    println('ǅ'.isUpperCase())
    println('ª'.isLetter())
    println('ª'.isLowerCase())
    println('Ⅷ'.isUpperCase())
    println('ⅷ'.isLowerCase())
    println('٣'.isDigit())
    println('٣'.digitToInt())
    println('٣'.digitToIntOrNull())
    println('７'.digitToInt())
    println('Ａ'.digitToInt(16))
    println('²'.isDigit())
    println('x'.digitToIntOrNull())
    println('9'.digitToIntOrNull(8))
    println('é'.isLetterOrDigit())
    println('€'.isLetterOrDigit())
    println(' '.isWhitespace())
    println(' '.isWhitespace())
    println('　'.isWhitespace())
    println('\u001F'.isWhitespace())
    println('\u0085'.isWhitespace())
    println('​'.isWhitespace())
    println('͸'.isDefined())
    println('a'.isDefined())
    println("a　b  c".split(' ', '　', ' ').size)
    println("   x　 ".trim())
    println('ÿ'.uppercaseChar())
    println('µ'.uppercaseChar().code)
    println('Ÿ'.lowercaseChar())
    println('ǅ'.uppercaseChar())
    println('ǅ'.lowercaseChar())
    println('ᾳ'.uppercaseChar().code)
    println('Σ'.lowercaseChar())
    println('σ'.uppercaseChar())
    println('ς'.uppercaseChar())
    println('é'.equals('É', ignoreCase = true))
    println('σ'.equals('ς', ignoreCase = true))
    println("Éa".equals("éA", ignoreCase = true))
    println("hello wörld".replaceFirstChar { it.uppercaseChar() })
    println("élan".capitalize())
    println("élan vital".split(" ").joinToString(" ") { it.replaceFirstChar { c -> c.titlecase() } })
    println('ß'.uppercase())
    println('ß'.titlecase())
    println('ǆ'.titlecase())
    println("ǆ".uppercase())
}
